Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{ass:pos-mono}{ass:normalize}, and the CFL condition
\begin{align}
\lambda \Big(\|V\|_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^{\infty}}\Big) \leq1
\end{align} holds. Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Then the following uniform bounds hold:
\begin{align*}
    \rho_{\mathrm{min}} \leq \rho_j^n \leq \rho_{\mathrm{max}} \qquad \textnormal{for all } j\in\mathbb{Z}, \ n\geq0,
\end{align*}
where $\rho_{\mathrm{min}}\coloneqq\inf_{x\in\mathbb{R}}\rho_0(x)\geq0$ and $\rho_{\mathrm{max}}\coloneqq\sup_{x\in\mathbb{R}}\rho_0(x)\leq1$.

Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{ass:pos-mono}{ass:convexity}, and the CFL condition 2.6 holds. Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Then the following spatial $\mathrm{TV}$-estimate holds: 
\begin{align}
\sum_{j\in\mathbb{Z}} |W_{j+1}^{n+1}-W_j^{n+1}| \le \sum_{j\in\mathbb{Z}} |W_{j+1}^n-W_j^n| \leq \mathrm{TV}(\rho_0), \qquad \textnormal{for all $n\ge0$.}
\end{align}

Under the conditions of 3.4,  the following temporal $\mathrm{TV}$-estimate holds:  
\begin{align}
    \sum_{j\in\mathbb{Z}} |W_j^{n+1}-W_j^n| \leq \lambda \left(\|V\|_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^{\infty}}\right) \mathrm{TV}(\rho_0), \qquad \textnormal{for all $n\ge0$.}
\end{align}

Under the conditions of 3.1, the following discrete entropy inequality holds:
\begin{align}
    &\frac{|W_j^{n+1}-c| -|W_j^n-c|}{\tau} + \frac{\Psi_{j+1/2}^n - \Psi_{j-1/2}^n}{h} \leq 0, \qquad \mathrm{for\ all}\  c\in\mathbb{R}, \\
     &\mathrm{with} \quad \Psi_{j-1/2}^n \coloneqq |W_{j-1}^n-c|V(c) - \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k-1}^n \left|V(W_{j+k}^n)-V(c)\right|.
\end{align}

Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy  \crefrange{ass:pos-mono}{ass:convexity} and 2.5, and the CFL condition 2.6 holds with the CFL ratio $\lambda\coloneqq \tau/h$ fixed. Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Let $W_{{\varepsilon},h}$ be the approximate solution constructed from $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ using 2.7, and $\rho$ be the unique entropy solution of 1.6.
Then the following error estimate holds:
\begin{align*}
\|W_{{\varepsilon},h}(T,\cdot)-\rho(T,\cdot)\|_{\mathrm{L}^1} \leq K\left( {\varepsilon}+h+\sqrt{{\varepsilon}\, T}+\sqrt{h\, T} \right) \mathrm{TV}(\rho_0), \quad \textnormal{for every } {\varepsilon},h > 0, \, T > 0,
\end{align*}
where the constant $K>0$ only depends on $\lambda$, $\|V\|_{\mathrm{L}^\infty}$, $\|V'\|_{\mathrm{L}^\infty}$, and $c_\gamma$ (as specified in 2.5).

Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{ass:pos-mono}{eq:quad_weight_localize}, and the CFL condition 
\begin{align}
   \lambda \Big(\left\lVert V\right\rVert_{\mathrm{L}^\infty}+2\|V'\|_{\mathrm{L}^\infty}\Big) \leq 1
\end{align}
holds, with the CFL ratio $\lambda\coloneqq \tau/h$ fixed. Let us consider the numerical solutions $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}, and let $W_{{\varepsilon},h}$ be the piecewise constant reconstruction of $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$, i.\,e., 
\begin{align}
    W_{{\varepsilon},h} \coloneqq \sum_{n=0}^\infty \sum_{j\in\mathbb{Z}} W_j^n \,\cdot\, \mathds{1}_{[n\tau,(n+1)\tau[\times[(j-\frac12)h,(j+\frac12)h[}.
\end{align}
Then, as ${\varepsilon},h\searrow 0$, the approximate solution $W_{{\varepsilon},h}$ converges strongly in $\mathrm{L}^1_{\mathrm{loc}}$ to the unique entropy solution $\rho$ of 1.6. 
Moreover, assuming 2.5, the following error estimate holds: 
\begin{align}
\|W_{{\varepsilon},h}(t,\cdot)-\rho(t,\cdot)\|_{\mathrm{L}^1} \leq K\left( {\varepsilon}+h+\sqrt{{\varepsilon}\, t}+\sqrt{h\,t} \right)\, \mathrm{TV}(\rho_0), \quad \textnormal{for every } {\varepsilon},h > 0, \, t > 0,
\end{align}
where the constant $K>0$ only depends on $\lambda$, $\|V\|_{\mathrm{L}^\infty}$, $\|V'\|_{\mathrm{L}^\infty}$, and $c_\gamma$ (as specified in 2.5).

Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{eq:geometric-gamma}{eq:geometric-gamma-assm}, and the CFL condition 3.1 holds. 
Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Then the spatial $\mathrm{TV}$-estimate 3.4 holds.

Under the conditions of 3.4,  the following temporal $\mathrm{TV}$-estimate holds:  
\begin{align}
    \sum_{j\in\mathbb{Z}} |W_j^{n+1}-W_j^n| \leq \lambda \left(\|V\|_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^{\infty}}\right) \mathrm{TV}(\rho_0), \qquad \textnormal{for all $n\ge0$.}
\end{align}

Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{eq:geometric-gamma}{eq:geometric-gamma-assm}, and the CFL condition 3.1 holds. 
Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Then the following discrete entropy inequality holds: 
\begin{align}
    \frac{|\rho_j^{n+1}-c|-|\rho_j^n-c|}{\tau} + \frac{\Psi_c(\rho_j^n, W_{j+1}^n) - \Psi_c(\rho_{j-1}^n, W_j^n)}{h} \leq 0,
\end{align}
for all $c \in \mathbb{R}$ and  $\Psi_c(\rho,W)\coloneqq |\rho-c|V(W) - c|V(W)-V(c)|$.

Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{eq:geometric-gamma}{eq:geometric-gamma-assm}, and the CFL condition 3.1 holds with the CFL ratio $\lambda\coloneqq \tau/h$ fixed.
 Let us consider the numerical solutions $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}, and let $\rho_{{\varepsilon},h}$ and $W_{{\varepsilon},h}$ be the piecewise constant reconstructions of $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$, respectively, i.\,e., 
\begin{align*}
     \rho_{{\varepsilon},h} &\coloneqq  \sum_{n=0}^\infty \sum_{j\in\mathbb{Z}} \rho_j^n \cdot \mathds{1}_{[n\tau,(n+1)\tau[\times[(j-\frac12)h,(j+\frac12)h[}, \\
    W_{{\varepsilon},h} &\coloneqq \sum_{n=0}^\infty \sum_{j\in\mathbb{Z}} W_j^n \cdot \mathds{1}_{[n\tau,(n+1)\tau[\times[(j-\frac12)h,(j+\frac12)h[}.
\end{align*}
Then, as ${\varepsilon},h\searrow 0$, both approximate solutions $W_{\varepsilon, h}$ and $\rho_{\varepsilon, h}$ converge strongly in $\mathrm{L}^1_{\mathrm{loc}}$ to the unique entropy solution $\rho$ of 1.6.
Moreover, the following error estimates hold: 
\begin{align}
\|W_{{\varepsilon},h}(t,\cdot)-\rho(t,\cdot)\|_{\mathrm{L}^1} &\leq K\left( {\varepsilon}+h+\sqrt{{\varepsilon}\, t}+\sqrt{h\,t} \right) \, \mathrm{TV}(\rho_0), \quad \textnormal{for every } {\varepsilon},h > 0, \, t > 0,  \\
\|\rho_{{\varepsilon},h}(t,\cdot)-\rho(t,\cdot)\|_{\mathrm{L}^1} &\leq K\left( {\varepsilon}+h+\sqrt{{\varepsilon}\, t}+\sqrt{h\,t} \right)\, \mathrm{TV}(\rho_0), \quad \textnormal{for every } {\varepsilon},h > 0, \, t > 0, 
\end{align}
where the constant $K>0$ only depends on $\lambda$, $\|V\|_{\mathrm{L}^\infty}$, $\|V'\|_{\mathrm{L}^\infty}$, and $c_\gamma$ (as in 4.4).

Let us suppose that the quadrature weights satisfy \crefrange{eq:geometric-gamma}{eq:geometric-gamma-assm}. Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Then the following $\mathrm{L}^1$-estimate holds:
    \begin{align}
        \sum_{j \in \mathbb Z} |W_j^n-\rho_j^n| h \leq c\,{\varepsilon}  \sum_{j \in \mathbb Z} |W^n_{j+1} - W^n_j|,
    \end{align}
    where the constant $c>0$ is as in 4.4, independent of ${\varepsilon},h$.
